def f1_score(cm):
    """
    F1 score is the harmonic mean of precision and sensitivity
    F1 = 2 TP / (2 TP + FP + FN)
    """
    return 2 * cm[1][1] / float(2 * cm[1][1] + cm[0][1] + cm[1][0])

